<template>
  <div class="content-wrap"><div class="detail-heading"><router-link to="/interviews" class="back-link"><ArrowLeft :size="15" />{{ t('common.back') }}</router-link><div><p class="eyebrow">{{ t('detail.eyebrow') }}</p><h1 class="page-title">{{ t('detail.title') }} #{{ interviewId }}</h1></div></div><div v-if="loading" class="card loading-state"><LoaderCircle class="spin" :size="22" /><span>{{ t('common.loading') }}</span></div><template v-else-if="detail"><section class="card info-card"><div><span>{{ t('detail.role') }}</span><strong>{{ detail.target_position }}</strong></div><div><span>{{ t('detail.difficulty') }}</span><strong>{{ difficultyLabel(detail.difficulty) }}</strong></div><div><span>{{ t('detail.questions') }}</span><strong>{{ detail.total_questions }}</strong></div><div><span>{{ t('detail.overall') }}</span><strong :style="{ color: detail.overall_score != null ? scoreColor(detail.overall_score) : 'var(--text-faint)' }">{{ detail.overall_score ?? '-' }}</strong></div><div><span>{{ t('detail.status') }}</span><span :class="['badge', detail.status === 'completed' ? 'badge-green' : 'badge-yellow']">{{ detail.status === 'completed' ? t('common.completed') : t('common.inProgress') }}</span></div></section><section class="card report-card" v-if="detail.report?.summary"><div class="section-heading"><FileText :size="18" /><h2>{{ t('detail.report') }}</h2></div><p class="long-copy">{{ detail.report.summary }}</p><div class="report-cols"><div v-if="detail.report.strengths?.length"><h3>{{ t('detail.strengths') }}</h3><ul><li v-for="(item,index) in detail.report.strengths" :key="index">{{ item }}</li></ul></div><div v-if="detail.report.weaknesses?.length"><h3>{{ t('detail.weaknesses') }}</h3><ul><li v-for="(item,index) in detail.report.weaknesses" :key="index">{{ item }}</li></ul></div></div></section><section class="card report-card"><div class="section-heading"><MessagesSquare :size="18" /><h2>{{ t('detail.conversation') }}</h2></div><div v-for="message in detail.messages" :key="message.id" :class="['message-row', message.role]"><div class="message-meta"><span class="message-avatar"><Sparkles v-if="message.role === 'interviewer'" :size="14" /><UserRound v-else :size="14" /></span><strong>{{ message.role === 'interviewer' ? t('detail.interviewer') : t('detail.candidate') }}</strong></div><p>{{ message.content }}</p><span v-if="message.score != null" class="message-score">{{ t('detail.rating') }} {{ message.score }}/10<span v-if="message.feedback"> · {{ message.feedback }}</span></span></div></section></template></div>
</template>
<script setup>
import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRoute } from 'vue-router'; import { ArrowLeft, FileText, LoaderCircle, MessagesSquare, Sparkles, UserRound } from '@lucide/vue'; import { interviewApi } from '../api'
const { t } = useI18n(); const route = useRoute(); const interviewId = route.params.id; const detail = ref(null); const loading = ref(true)
function difficultyLabel(value) { return t(`common.${value}`, value) } function scoreColor(value) { return value >= 7 ? 'var(--success)' : value >= 5 ? 'var(--warning)' : 'var(--danger)' }
interviewApi.detail(interviewId).then(data => { detail.value = data }).catch(e => console.error(e)).finally(() => { loading.value = false })
</script>
