.info-card { display:grid; grid-template-columns:repeat(5,1fr); gap:18px; } .info-card > div { display:flex; flex-direction:column; gap:8px; } .info-card > div > span:first-child { color:var(--text-faint); font-size:11px; } .info-card strong { color:var(--text); font-size:14px; font-weight:650; } .report-card { margin-top:16px; } .section-heading { display:flex; align-items:center; gap:10px; margin-bottom:16px; } .section-heading svg { color:var(--text-soft); } .section-heading h2 { font-size:17px; font-weight:650; } .long-copy,.report-cols li,.message-row p { color:var(--text-soft); font-size:13px; line-height:1.8; } .report-cols { display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:22px; } .report-cols h3 { margin-bottom:8px; color:var(--text-soft); font-size:12px; } .report-cols ul { padding-left:16px; }
.message-row { margin-top:16px; padding:17px; border:1px solid var(--border); border-radius:var(--radius-md); background:var(--bg-soft); } .message-row.candidate { background:var(--bg-hover); } .message-meta { display:flex; align-items:center; gap:8px; margin-bottom:9px; color:var(--text-soft); font-size:11px; } .message-avatar { width:26px; height:26px; display:grid; place-items:center; border:1px solid var(--border); border-radius:50%; color:var(--text-soft); background:var(--bg-elevated); } .message-score { display:block; margin-top:9px; color:var(--text-faint); font-size:11px; }
