@media(max-width:820px) { .info-card { grid-template-columns:repeat(3,1fr); } } @media(max-width:560px) { .detail-heading { gap:10px; } .info-card { grid-template-columns:1fr 1fr; } .report-cols { grid-template-columns:1fr; } }
